-- Server mirror of the v2615 client Data\TICKET_EXCHANGE.tbl.
-- The client sends ticket/reward IDs, but GameServer owns validation,
-- consumption, duration and reward delivery. duration_hours is converted to
-- expiry days only when the value is non-zero.

CREATE TABLE IF NOT EXISTS native_ticket_exchange_rule (
    ticket_item_id INTEGER NOT NULL,
    reward_item_id INTEGER NOT NULL,
    duration_hours INTEGER NOT NULL DEFAULT 0 CHECK (duration_hours >= 0),
    selector SMALLINT NOT NULL DEFAULT 0,
    PRIMARY KEY (ticket_item_id, reward_item_id)
);

ON CONFLICT (ticket_item_id, reward_item_id) DO UPDATE SET
    duration_hours = EXCLUDED.duration_hours,
    selector = EXCLUDED.selector;

CREATE INDEX IF NOT EXISTS idx_native_ticket_exchange_reward
    ON native_ticket_exchange_rule (reward_item_id);
